package tui

import (
	"encoding/json"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"testing"
)

// The Pi vectors: what the pinned pi-tui package's own functions return (test/parity/sdk-vectors/pi-tui/<export>.json, generated by
// automation/gen/generate-sdk-vectors.mjs). Every case of every file is run.
type piCase struct {
	Name   string
	Args   []any
	Result any
	Throws *string
}

func loadPi(t *testing.T, export string) []piCase {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("..", "..", "..", "test", "parity", "sdk-vectors", "pi-tui", export+".json"))
	if err != nil {
		t.Fatal(err)
	}
	var f struct{ Cases []piCase }
	if err := json.Unmarshal(raw, &f); err != nil {
		t.Fatal(err)
	}
	if len(f.Cases) == 0 {
		t.Fatalf("%s has no cases", export)
	}
	return f.Cases
}

func isUndefined(v any) bool { m, ok := v.(map[string]any); return ok && m["$"] == "undefined" }

func argInt(v any) int { return int(v.(float64)) }

func piColor(v any) Color {
	m := v.(map[string]any)
	switch m["kind"] {
	case "indexed":
		return IndexedColor{Index: argInt(m["index"])}
	case "rgb":
		return RgbColorValue{R: m["r"].(float64), G: m["g"].(float64), B: m["b"].(float64)}
	}
	return OklchColorValue{L: m["l"].(float64), C: m["c"].(float64), H: m["h"].(float64)}
}

func colorMap(c Color) any {
	switch c := c.(type) {
	case IndexedColor:
		return map[string]any{"kind": "indexed", "index": float64(c.Index)}
	case RgbColorValue:
		return map[string]any{"kind": "rgb", "r": c.R, "g": c.G, "b": c.B}
	case OklchColorValue:
		return map[string]any{"kind": "oklch", "l": c.L, "c": c.C, "h": c.H}
	}
	return nil
}

func piNear(got, want any) bool {
	switch w := want.(type) {
	case float64:
		g, ok := got.(float64)
		return ok && (g == w || math.Abs(g-w) <= 1e-9*math.Max(1, math.Abs(w)))
	case map[string]any:
		g, ok := got.(map[string]any)
		if !ok || len(g) != len(w) {
			return false
		}
		neutral := false
		for _, k := range []string{"c", "s"} {
			if c, ok := w[k].(float64); ok && c < 1e-9 {
				neutral = true
			}
		}
		for k, x := range w {
			if (k != "h" || !neutral) && !piNear(g[k], x) {
				return false
			}
		}
		return true
	case []any:
		g, ok := got.([]any)
		if !ok || len(g) != len(w) {
			return false
		}
		for i := range w {
			if !piNear(g[i], w[i]) {
				return false
			}
		}
		return true
	}
	return got == want
}

func TestPiVectors(t *testing.T) {
	str := func(v any) string { return v.(string) }
	optional := func(s string, ok bool) any {
		if !ok {
			return map[string]any{"$": "undefined"}
		}
		return s
	}
	run := map[string]func(a []any) (any, error){
		"visibleWidth":           func(a []any) (any, error) { return float64(VisibleWidth(str(a[0]))), nil },
		"stripTerminalSequences": func(a []any) (any, error) { return StripTerminalSequences(str(a[0])), nil },
		"truncateToWidth": func(a []any) (any, error) {
			if len(a) == 2 {
				return TruncateToWidth(str(a[0]), argInt(a[1]), DefaultEllipsis, false), nil
			}
			return TruncateToWidth(str(a[0]), argInt(a[1]), str(a[2]), a[3].(bool)), nil
		},
		"wrapTextWithAnsi": func(a []any) (any, error) {
			lines := WrapTextWithAnsi(str(a[0]), argInt(a[1]))
			out := make([]any, len(lines))
			for i, l := range lines {
				out[i] = l
			}
			return out, nil
		},
		"sliceByColumn": func(a []any) (any, error) {
			return SliceByColumn(str(a[0]), argInt(a[1]), argInt(a[2]), a[3].(bool)), nil
		},
		"getOsc8LinkAtColumn": func(a []any) (any, error) {
			url, ok := GetOsc8LinkAtColumn(str(a[0]), argInt(a[1]))
			return optional(url, ok), nil
		},
		"fuzzyMatch": func(a []any) (any, error) {
			r := FuzzyMatch(str(a[0]), str(a[1]))
			return map[string]any{"matches": r.Matches, "score": r.Score}, nil
		},
		"fuzzyFilter": func(a []any) (any, error) {
			var items []string
			for _, i := range a[0].([]any) {
				items = append(items, str(i))
			}
			got := FuzzyFilter(items, str(a[1]), func(s string) string { return s })
			out := make([]any, len(got))
			for i, g := range got {
				out[i] = g
			}
			return out, nil
		},
		"parseKey":             func(a []any) (any, error) { id, ok := ParseKey(str(a[0])); return optional(id, ok), nil },
		"isKeyRelease":         func(a []any) (any, error) { return IsKeyRelease(str(a[0])), nil },
		"isKeyRepeat":          func(a []any) (any, error) { return IsKeyRepeat(str(a[0])), nil },
		"decodeKittyPrintable": func(a []any) (any, error) { s, ok := DecodeKittyPrintable(str(a[0])); return optional(s, ok), nil },
		"matchesKey":           func(a []any) (any, error) { return MatchesKey(str(a[0]), str(a[1])), nil },
		"hyperlink":            func(a []any) (any, error) { return Hyperlink(str(a[0]), str(a[1])), nil },
		"CURSOR_MARKER":        func(a []any) (any, error) { return CursorMarker, nil },
		"parseColor": func(a []any) (any, error) {
			var c Color
			var err error
			if n, ok := a[0].(float64); ok {
				c, err = ParseColor(n)
			} else {
				c, err = ParseColor(str(a[0]))
			}
			return colorMap(c), err
		},
		"rgbColor": func(a []any) (any, error) {
			c, err := NewRgbColor(a[0].(float64), a[1].(float64), a[2].(float64))
			return colorMap(c), err
		},
		"oklchColor": func(a []any) (any, error) {
			c, err := NewOklchColor(a[0].(float64), a[1].(float64), a[2].(float64))
			return colorMap(c), err
		},
		"okhslColor": func(a []any) (any, error) {
			c, err := NewOkhslColor(a[0].(float64), a[1].(float64), a[2].(float64))
			return colorMap(c), err
		},
		"indexedColor": func(a []any) (any, error) {
			f := a[0].(float64)
			if f != math.Trunc(f) {
				return nil, fmt.Errorf("ANSI color index must be an integer from 0 to 255: %v", f)
			}
			c, err := NewIndexedColor(int(f))
			return colorMap(c), err
		},
		"colorToRgb": func(a []any) (any, error) {
			r := ColorToRgb(piColor(a[0]))
			return map[string]any{"r": r.R, "g": r.G, "b": r.B}, nil
		},
		"colorToHex": func(a []any) (any, error) { return ColorToHex(piColor(a[0])), nil },
		"colorToOklch": func(a []any) (any, error) {
			o := ColorToOklch(piColor(a[0]))
			return map[string]any{"l": o.L, "c": o.C, "h": o.H}, nil
		},
		"colorToOkhsl": func(a []any) (any, error) {
			o := ColorToOkhsl(piColor(a[0]))
			return map[string]any{"h": o.H, "s": o.S, "l": o.L}, nil
		},
		"foregroundAnsi": func(a []any) (any, error) { return ForegroundAnsi(piColor(a[0]), TerminalColorMode(str(a[1]))), nil },
		"backgroundAnsi": func(a []any) (any, error) { return BackgroundAnsi(piColor(a[0]), TerminalColorMode(str(a[1]))), nil },
		"mixColors": func(a []any) (any, error) {
			space := ColorMixSpaceOklch
			if s, ok := a[3].(string); ok {
				space = ColorMixSpace(s)
			}
			c, err := MixColors(piColor(a[0]), piColor(a[1]), a[2].(float64), space)
			return colorMap(c), err
		},
		"styleText": func(a []any) (any, error) {
			o := a[1].(map[string]any)
			style := TextStyle{TextAttributes: attrs(o)}
			if v, ok := o["fg"]; ok {
				style.Fg = piColor(v)
			}
			if v, ok := o["bg"]; ok {
				style.Bg = piColor(v)
			}
			return StyleText(str(a[0]), style, TerminalColorMode(str(a[2]))), nil
		},
		"styleTextWithAnsi": func(a []any) (any, error) {
			fg, _ := a[1].(string)
			bg, _ := a[2].(string)
			return StyleTextWithAnsi(str(a[0]), fg, bg, attrs(a[3].(map[string]any))), nil
		},
	}
	for export, fn := range run {
		cases := loadPi(t, export)
		fails := 0
		for _, c := range cases {
			got, err := fn(c.Args)
			switch {
			case c.Throws != nil:
				if err == nil || err.Error() != *c.Throws {
					fails++
					t.Errorf("%s %s: error %v, Pi throws %q", export, c.Name, err, *c.Throws)
				}
			case err != nil || !piNear(got, c.Result) && (!isUndefined(c.Result) || !isUndefined(got)):
				fails++
				t.Errorf("%s %s(%v) = %v (err %v), Pi %v", export, c.Name, c.Args, got, err, c.Result)
			}
			if fails > 5 {
				break
			}
		}
	}
}

func attrs(o map[string]any) TextAttributes {
	return TextAttributes{Bold: o["bold"] == true, Dim: o["dim"] == true, Italic: o["italic"] == true, Underline: o["underline"] == true, Inverse: o["inverse"] == true, Strikethrough: o["strikethrough"] == true}
}
